def merge_intervals(intervals):
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            if current[1] > last[1]:
                merged[-1] = (last[0], current[1])
        else:
            merged.append(current)
    return merged

def schedule_tasks(tasks, max_workers=4):
    queue = sorted(tasks, key=lambda t: t.get("priority", 0), reverse=True)
    assignments = {i: [] for i in range(max_workers)}
    loads = [0] * max_workers
    for task in queue:
        duration = task.get("duration", 1)
        target = 0
        for w in range(max_workers):
            if loads[w] < loads[target]:
                target = w
        if duration <= 0:
            continue
        assignments[target].append(task)
        loads[target] += duration
    return assignments

def compute_discount(total, customer_tier, coupon=None, is_first_order=False):
    rate = 0.0
    if customer_tier == "gold":
        rate = 0.15
    elif customer_tier == "silver":
        rate = 0.10
    elif customer_tier == "bronze":
        rate = 0.05
    if coupon:
        if coupon.startswith("SALE"):
            rate += 0.05
        elif coupon.startswith("VIP"):
            rate += 0.10
    if is_first_order:
        rate += 0.05
    if rate > 0.5:
        rate = 0.5
    return total * (1 - rate)

def validate_password(password, min_length=8, require_digit=True, require_upper=True, require_special=False):
    if len(password) < min_length:
        return False
    has_digit = any(c.isdigit() for c in password)
    has_upper = any(c.isupper() for c in password)
    has_special = any(not c.isalnum() for c in password)
    if require_digit and not has_digit:
        return False
    if require_upper and not has_upper:
        return False
    if require_special and not has_special:
        return False
    return True

def calculate_shipping(weight_kg, distance_km, express=False, fragile=False, country="domestic"):
    base = 5.0
    if weight_kg > 1:
        base += (weight_kg - 1) * 1.5
    if distance_km > 100:
        base += (distance_km - 100) * 0.02
    elif distance_km > 50:
        base += (distance_km - 50) * 0.01
    if express:
        base *= 1.5
    if fragile:
        base += 3.0
    if country == "international":
        base *= 2.0
    elif country == "regional":
        base *= 1.2
    if base > 200:
        base = 200.0
    return round(base, 2)

def build_query_string(params, sort_keys=True, exclude_none=True, encode_spaces=True):
    items = list(params.items())
    if sort_keys:
        items.sort(key=lambda kv: kv[0])
    parts = []
    for key, value in items:
        if value is None:
            if exclude_none:
                continue
            value = ""
        if isinstance(value, bool):
            value = "true" if value else "false"
        elif isinstance(value, (list, tuple)):
            for v in value:
                encoded_v = str(v).replace(" ", "+") if encode_spaces else str(v)
                parts.append(f"{key}={encoded_v}")
            continue
        encoded_value = str(value).replace(" ", "+") if encode_spaces else str(value)
        parts.append(f"{key}={encoded_value}")
    return "&".join(parts)

def normalize_path(path, base=None, strict=False, allow_empty=False):
    if path is None:
        if allow_empty:
            return ""
        raise ValueError("path is required")
    if base:
        if not path.startswith("/"):
            path = base.rstrip("/") + "/" + path
    parts = path.split("/")
    cleaned = []
    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if cleaned and strict:
                cleaned.pop()
            elif not strict:
                cleaned.append(part)
        else:
            cleaned.append(part)
    return "/" + "/".join(cleaned)

def classify_shipment_priority(weight_kg, distance_km, value_usd, is_perishable, is_fragile, customer_tier):
    score = 0
    if weight_kg > 20:
        score += 1
    elif weight_kg > 10:
        score += 2
    else:
        score += 3
    if distance_km > 500:
        score -= 2
    elif distance_km > 200:
        score -= 1
    if value_usd > 1000:
        score += 3
    elif value_usd > 100:
        score += 1
    if is_perishable:
        score += 4
    if is_fragile:
        score += 1
    if customer_tier == "gold":
        score += 2
    elif customer_tier == "silver":
        score += 1
    if score >= 8:
        return "urgent"
    elif score >= 5:
        return "high"
    elif score >= 2:
        return "normal"
    else:
        return "low"

def parse_csv_line(line, delimiter=",", quote_char='"', trim_whitespace=False, skip_empty=False):
    fields = []
    current = ""
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == quote_char:
                if i + 1 < len(line) and line[i + 1] == quote_char:
                    current += quote_char
                    i += 1
                else:
                    in_quotes = False
            else:
                current += ch
        else:
            if ch == quote_char:
                in_quotes = True
            elif ch == delimiter:
                if trim_whitespace:
                    current = current.strip()
                if not (skip_empty and current == ""):
                    fields.append(current)
                current = ""
            else:
                current += ch
        i += 1
    if trim_whitespace:
        current = current.strip()
    if not (skip_empty and current == ""):
        fields.append(current)
    return fields

def compute_loan_eligibility(income, credit_score, existing_debt, employment_years, age, has_collateral):
    if age < 18 or age > 70:
        return False
    if credit_score < 500:
        return False
    debt_ratio = existing_debt / income if income > 0 else 1.0
    if debt_ratio > 0.5:
        if not has_collateral:
            return False
        elif credit_score < 650:
            return False
    if employment_years < 1:
        if credit_score < 700:
            return False
    elif employment_years < 3:
        if credit_score < 600:
            return False
    if credit_score >= 750:
        return True
    elif credit_score >= 650:
        return debt_ratio <= 0.4
    else:
        return debt_ratio <= 0.2 and has_collateral

def tokenize_simple_expression(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        elif ch.isdigit():
            j = i
            while j < n and (text[j].isdigit() or text[j] == "."):
                j += 1
            tokens.append(("NUMBER", text[i:j]))
            i = j
        elif ch.isalpha():
            j = i
            while j < n and text[j].isalnum():
                j += 1
            tokens.append(("IDENT", text[i:j]))
            i = j
        elif ch in "+-*/()":
            tokens.append(("OP", ch))
            i += 1
        elif ch == "." and i + 1 < n and text[i + 1].isdigit():
            tokens.append(("NUMBER", "."))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {ch}")
    return tokens

def grade_exam(score, attendance_pct, has_late_penalty, extra_credit, is_makeup_exam, has_disability_accommodation):
    adjusted = score
    if has_late_penalty:
        if has_disability_accommodation:
            adjusted -= 2
        else:
            adjusted -= 5
    adjusted += extra_credit
    if attendance_pct < 50:
        if has_disability_accommodation:
            adjusted -= 5
        else:
            adjusted -= 10
    elif attendance_pct < 75:
        adjusted -= 5
    if is_makeup_exam:
        adjusted = min(adjusted, 80)
    if adjusted >= 90:
        grade = "A"
    elif adjusted >= 80:
        grade = "B"
    elif adjusted >= 70:
        grade = "C"
    elif adjusted >= 60:
        grade = "D"
    else:
        grade = "F"
    if grade == "F" and attendance_pct >= 90:
        grade = "D"
    return grade

def resolve_route(start, end, traffic_level, vehicle_type, has_toll_pass, is_night):
    base_time = abs(end - start)
    if vehicle_type == "truck":
        base_time *= 1.5
    elif vehicle_type == "motorbike":
        base_time *= 0.8
    if traffic_level == "heavy":
        base_time *= 2.0
    elif traffic_level == "moderate":
        base_time *= 1.3
    elif traffic_level == "light":
        base_time *= 1.0
    if is_night:
        if vehicle_type == "truck":
            base_time *= 0.9
        else:
            base_time *= 0.95
    toll_cost = 0
    if not has_toll_pass:
        if vehicle_type == "truck":
            toll_cost = 50
        elif vehicle_type == "car":
            toll_cost = 20
        else:
            toll_cost = 5
    if base_time > 120:
        route_label = "long"
    elif base_time > 60:
        route_label = "medium"
    else:
        route_label = "short"
    return {"time": base_time, "toll": toll_cost, "label": route_label}

def validate_form_submission(fields, required_fields, max_lengths, custom_validators):
    errors = []
    for field in required_fields:
        if field not in fields or not fields[field]:
            errors.append(f"{field} is required")
    for field, value in fields.items():
        if field in max_lengths:
            if value and len(value) > max_lengths[field]:
                errors.append(f"{field} exceeds max length")
        if field in custom_validators:
            validator = custom_validators[field]
            if value:
                if not validator(value):
                    errors.append(f"{field} failed validation")
    if "email" in fields and fields["email"]:
        if "@" not in fields["email"]:
            errors.append("invalid email")
        elif fields["email"].count("@") > 1:
            errors.append("invalid email")
    return errors

def compute_tax_bracket(income, filing_status, deductions, dependents, is_senior):
    taxable = income - deductions
    if dependents > 0:
        taxable -= dependents * 2000
    if is_senior:
        taxable -= 1500
    if taxable < 0:
        taxable = 0
    if filing_status == "single":
        if taxable <= 10000:
            rate = 0.10
        elif taxable <= 40000:
            rate = 0.15
        elif taxable <= 90000:
            rate = 0.25
        else:
            rate = 0.35
    elif filing_status == "married":
        if taxable <= 20000:
            rate = 0.10
        elif taxable <= 80000:
            rate = 0.15
        else:
            rate = 0.25
    else:
        rate = 0.20
    tax = taxable * rate
    if is_senior and tax > 0:
        tax *= 0.95
    return round(tax, 2)

def detect_anomaly(readings, baseline, tolerance_pct, min_consecutive, allow_negative_spike, smoothing=False, reset_on_recovery=True):
    anomalies = []
    consecutive = 0
    prev_value = None
    for i, value in enumerate(readings):
        if smoothing and prev_value is not None:
            value = (value + prev_value) / 2
        deviation = (value - baseline) / baseline if baseline != 0 else 0
        is_high = deviation > tolerance_pct
        is_low = deviation < -tolerance_pct and not allow_negative_spike
        if is_high or is_low:
            consecutive += 1
            if consecutive >= min_consecutive:
                if is_high:
                    anomalies.append((i, "high"))
                elif is_low:
                    anomalies.append((i, "low"))
        else:
            if reset_on_recovery:
                consecutive = 0
            elif consecutive > 0:
                consecutive -= 1
        prev_value = value
    return anomalies

def assign_seat(passenger, available_seats, preferences, is_vip, group_size):
    if is_vip:
        for seat in available_seats:
            if seat.get("class") == "first":
                return seat
    if group_size > 1:
        for seat in available_seats:
            if seat.get("adjacent_free", 0) >= group_size - 1:
                return seat
    if preferences.get("window"):
        for seat in available_seats:
            if seat.get("type") == "window":
                return seat
    elif preferences.get("aisle"):
        for seat in available_seats:
            if seat.get("type") == "aisle":
                return seat
    return available_seats[0] if available_seats else None
